WITH `t0` AS (SELECT `tenantId`, `entityId`, `version`, `market_stock_total` FROM `metric_group_ots_component_market_availability` FINAL WHERE `tenantId` = {p0:String}) SELECT ifNull(`__typedhouse_input`.`category`, {p1:String}) AS `category`, sum(`__typedhouse_input`.`stock`) AS `stock` FROM (SELECT `c`.`category` AS `category`, `a`.`market_stock_total` AS `stock` FROM (SELECT `entityId`, `category` FROM `entity_ots_component` WHERE `tenantId` = {p2:String} AND `state` = {p3:String}) AS `c` INNER ALL JOIN (SELECT `m`.`entityId` AS `entityId`, `m`.`market_stock_total` AS `market_stock_total` FROM `t0` AS `m` INNER ALL JOIN (SELECT `tenantId`, `entityId`, max(`version`) AS `version` FROM `t0` GROUP BY `tenantId`, `entityId`) AS `v` ON `m`.`tenantId` = `v`.`tenantId` AND `m`.`entityId` = `v`.`entityId` AND `m`.`version` = `v`.`version`) AS `a` ON `c`.`entityId` = `a`.`entityId`) AS `__typedhouse_input` GROUP BY ifNull(`__typedhouse_input`.`category`, {p1:String})
